    // Check if we have pre-loaded auditions data
    if (preloadedTrendingAuditions && Array.isArray(preloadedTrendingAuditions) && preloadedTrendingAuditions
        .length > 0) {
        const auditions = preloadedTrendingAuditions.slice(0, 4);
        renderAuditions(auditions);
        auditionsLoaded = true;
        return;
    }

    // Fallback: fetch from API if no pre-loaded data
    grid.html('<div class="auditions-loading">Loading...</div>');

    const storedAuditionsUrl = "https://members.naughtyamerica.com/feed/api/trending-auditions";

    $.ajax({
        url: storedAuditionsUrl,
        method: 'GET',
        dataType: 'json',
        success: function(storedResponse) {
            let auditions = [];

            // If we have stored auditions, use them; otherwise fetch latest
            if (storedResponse && storedResponse.data && Array.isArray(storedResponse.data) &&
                storedResponse.data.length > 0) {
                auditions = storedResponse.data.slice(0, 4);
                renderAuditions(auditions);
            } else {
                // Fallback to fetching latest auditions
                fetchLatestAuditions();
            }
        },
        error: function(xhr, status, error) {
            console.error('Error fetching stored auditions:', error);
            // If stored auditions endpoint fails, fetch latest
            fetchLatestAuditions();
        }
    });

    function fetchLatestAuditions() {
        const tagNextUrl = "https://members.naughtyamerica.com/feed/auditions/next";

        $.ajax({
            url: tagNextUrl,
            method: 'GET',
            data: {
                page: 1,
                sort: 'newest'
            },
            success: function(response) {
                if (response.data && response.data.length > 0) {
                    const auditions = response.data.slice(0, 4);
                    renderAuditions(auditions);
                } else {
                    grid.html('<div class="auditions-empty">No auditions available</div>');
                }
            },
            error: function() {
                grid.html('<div class="auditions-error">Failed to load auditions</div>');
            }
        });
    }

    function renderAuditions(auditions) {
        if (!auditions || auditions.length === 0) {
            grid.html('<div class="auditions-empty">No auditions available</div>');
            return;
        }

        let html = '';

        auditions.forEach(function(audition, index) {
            const imageUrl = audition.start_card_images?.image_600x1066_webp ||
                audition.start_card_images?.image_600x1066 ||
                'https://sm.naughtycdn.com/images/brokenImage.png';
            const title = audition.title || 'Untitled';
            const slug = audition.slug || '';
            const videoUrl = audition.is_locked ? '' : (audition
                .videoUrl_mp4_unbranded || audition.videoUrl_mp4 || '');
            const posterUrl = imageUrl;
            // Construct URL: /feed/video/{slug}?tag=auditions
            const feedUrl = '/feed/video/' + slug + '?tag=auditions&source_url=trending-dropdown';
            const itemId = 'audition-item-' + index;
            const starIconUrl = "/images/search/new-star-icon.png";
            html += `
                        <a href="${feedUrl}" class="audition-item" data-audition-id="${itemId}" onClick="trackAuditionClick('${title}', '${slug}', '${imageUrl}')">
                            <div class="audition-thumbnail" id="${itemId}">
                                <img src="${imageUrl}" alt="${title}" loading="lazy" />
                                ${videoUrl ? `
                                <video 
                                    preload="none" 
                                    muted 
                                    loop 
                                    playsinline 
                                    webkit-playsinline
                                    poster="${posterUrl}"
                                    data-video-url="${videoUrl}">
                                    <source src="${videoUrl}" type="video/mp4" />
                                </video>
                                ` : ''}
                                <div class="sponsor-tooltip">

                                    <img src="${starIconUrl}" alt="Star" class="sponsor-icon">
                                    <span class="sponsor-tooltip-text">Sponsor this Audition</span>
                                </div>
                            </div>
                            <div class="audition-label">${title}</div>
                        </a>
                    `;
        });

        grid.html(html);
        auditionsLoaded = true;

        // Initialize video hover functionality
        initializeVideoHover();
    }
}

// Video hover functionality
let currentPlayingVideo = null;

// Detect if device supports touch (mobile/tablet)
function isTouchDevice() {
    return ('ontouchstart' in window) ||
        (navigator.maxTouchPoints > 0) ||
        (navigator.msMaxTouchPoints > 0);
}

function initializeVideoHover() {
    // Skip video hover on touch devices to prevent double-tap issue
    if (isTouchDevice()) {
        return;
    }

    // Only initialize for non-search items (exclude .search-item)
    $('.audition-item:not(.search-item)').off('mouseenter mouseleave').on('mouseenter', function() {
        const $item = $(this);
        const $thumbnail = $item.find('.audition-thumbnail');
        const $video = $thumbnail.find('video');
        const $img = $thumbnail.find('img');

        // Stop any currently playing video and show its image
        if (currentPlayingVideo && currentPlayingVideo[0] !== $video[0]) {
            const $oldThumbnail = currentPlayingVideo.closest('.audition-thumbnail');
            currentPlayingVideo[0].pause();
            currentPlayingVideo[0].currentTime = 0;
            $oldThumbnail.removeClass('buffering video-loading video-buffering');
            // Show image on old thumbnail
            $oldThumbnail.find('img').css('opacity', '1');
        }

        // If video exists and hasn't been loaded yet
        if ($video.length && $video.attr('data-video-url')) {
            const videoElement = $video[0];
            const videoUrl = $video.attr('data-video-url');

            // Keep image visible while loading
            $thumbnail.addClass('video-loading');
            $img.css('opacity', '1');

            // Check if video source needs to be set
            const source = $video.find('source');
            if (!source.attr('src') || source.attr('src') !== videoUrl) {
                source.attr('src', videoUrl);
                videoElement.load();
            }

            // Show buffering indicator
            $thumbnail.addClass('buffering video-buffering');

            // Play video
            videoElement.play().then(function() {
                // Video is playing, now hide image
                $thumbnail.removeClass('buffering video-loading video-buffering');
                $img.css('opacity', '0');
                currentPlayingVideo = $video;
            }).catch(function(error) {
                console.log('Video play error:', error);
                $thumbnail.removeClass('buffering video-loading video-buffering');
                $img.css('opacity', '1');
            });
        }
    }).on('mouseleave', function() {
        const $item = $(this);
        const $video = $item.find('.audition-thumbnail video');
        const $thumbnail = $item.find('.audition-thumbnail');
        const $img = $thumbnail.find('img');

        if ($video.length) {
            const videoElement = $video[0];
            videoElement.pause();
            videoElement.currentTime = 0;
            $thumbnail.removeClass('buffering video-loading video-buffering');
            // Show image when leaving
            $img.css('opacity', '1');

            if (currentPlayingVideo && currentPlayingVideo[0] === videoElement) {
                currentPlayingVideo = null;
            }
        }
    });

    // Handle video events (only for non-search items)
    $('.audition-thumbnail:not(.search-thumbnail) video').off('waiting playing loadstart').on('waiting',
        function() {
            const $thumbnail = $(this).closest('.audition-thumbnail');
            $thumbnail.addClass('buffering video-buffering');
            // Keep image visible while waiting
            $thumbnail.find('img').css('opacity', '1');
        }).on('playing', function() {
        const $thumbnail = $(this).closest('.audition-thumbnail');
        $thumbnail.removeClass('buffering video-loading video-buffering');
        // Hide image when video is playing
        $thumbnail.find('img').css('opacity', '0');
    }).on('loadstart', function() {
        const $thumbnail = $(this).closest('.audition-thumbnail');
        $thumbnail.addClass('buffering video-loading');
        // Keep image visible while loading
        $thumbnail.find('img').css('opacity', '1');
    });
}

// Show dropdown on search input click/focus
$(document).ready(function() {
    const $searchInput = $('#search-bar-with-glass');
    const $dropdown = $('#auditions-dropdown');
    const $dropdownClose = $('.auditions-dropdown-close');

    // Show dropdown when clicking on search input (only if empty)
    $searchInput.on('click', function(e) {
        e.stopPropagation();

        if ($(this).val().length === 0) {
            // Use setTimeout to defer execution, ensuring dropdown is shown before document click handler runs
            setTimeout(function() {
                loadAuditionsDropdown();
            }, 0);
        }
    });

    // Show dropdown on focus (only if empty)
    $searchInput.on('focus', function(e) {
        e.stopPropagation();

        if ($(this).val().length === 0) {
            loadAuditionsDropdown();
        }
    });

    function closeAuditionsDropdown() {
        if ($dropdown.is(':visible')) {
            $('.audition-thumbnail video').each(function() {
                this.pause();
                this.currentTime = 0;
            });
            currentPlayingVideo = null;
            $dropdown.hide();
        }
    }

    $dropdownClose.on('click', function(e) {
        e.preventDefault();
        e.stopPropagation();
        closeAuditionsDropdown();
    });

    // Hide dropdown when clicking outside
    // Use setTimeout to ensure this runs after the input click handler
    $(document).on('click', function(e) {
        // Don't hide if clicking on search input, search container, or dropdown
        if ($(e.target).is('#search-bar-with-glass') ||
            $(e.target).closest('#search_new, #auditions-dropdown').length) {
            return;
        }

        // Only hide if dropdown is visible
        closeAuditionsDropdown();
    });

    // Hide dropdown when typing in search
    $searchInput.on('input', function() {
        if ($(this).val().length > 0) {
            closeAuditionsDropdown();
        }
    });
});

